//! Scientific smoke test: cytiq against what the upstream R tools computed on
//! the same small synthetic datasets (`data/fixtures/parity`, regenerated by
//! `parity/make_smoke.sh`). CI has no R; the full suites (`just parity`,
//! `just parity-real`) stay local. The bounds are those of
//! `parity/tolerances.json`.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::Value;

fn fixture(dataset: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../data/fixtures/parity")
        .join(dataset)
}

fn create_temp_dir(prefix: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock should be after epoch")
        .as_nanos();
    let directory = std::env::temp_dir().join(format!("{prefix}-{}-{nanos}", std::process::id()));
    fs::create_dir_all(&directory).expect("temp dir should be created");
    directory
}

fn utf8(path: &Path) -> &str {
    path.to_str().expect("path should be UTF-8")
}

fn cytiq(args: &[&str]) {
    let output = Command::new(env!("CARGO_BIN_EXE_cytiq"))
        .args(args)
        .output()
        .expect("command should run");
    assert!(
        output.status.success(),
        "cytiq {args:?}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

/// A CSV file as its header and string rows.
fn read_csv(path: &Path) -> (Vec<String>, Vec<Vec<String>>) {
    let mut reader = csv::Reader::from_path(path)
        .unwrap_or_else(|error| panic!("{} should be a CSV: {error}", path.display()));
    let header = reader
        .headers()
        .expect("header")
        .iter()
        .map(str::to_owned)
        .collect();
    let rows = reader
        .records()
        .map(|record| record.expect("row").iter().map(str::to_owned).collect())
        .collect();
    (header, rows)
}

/// The numeric columns of a CSV, by header name.
fn columns(path: &Path) -> HashMap<String, Vec<f64>> {
    let (header, rows) = read_csv(path);
    header
        .iter()
        .enumerate()
        .filter_map(|(index, name)| {
            rows.iter()
                .map(|row| row[index].parse::<f64>().ok())
                .collect::<Option<Vec<_>>>()
                .map(|values| (name.clone(), values))
        })
        .collect()
}

/// A square matrix CSV with row names in the first column, as `name -> name
/// -> value`.
fn matrix(path: &Path) -> HashMap<(String, String), f64> {
    let (header, rows) = read_csv(path);
    rows.iter()
        .flat_map(|row| {
            header[1..].iter().zip(&row[1..]).map(|(column, value)| {
                (
                    (row[0].clone(), column.clone()),
                    value.parse::<f64>().expect("matrix value"),
                )
            })
        })
        .collect()
}

/// Feature rows by file name, in column order, without `filename` and `path`.
fn features(path: &Path) -> HashMap<String, Vec<f64>> {
    let (header, rows) = read_csv(path);
    rows.iter()
        .map(|row| {
            let values = header
                .iter()
                .zip(row)
                .filter(|(name, _)| *name != "filename" && *name != "path")
                .map(|(name, value)| {
                    value
                        .parse::<f64>()
                        .unwrap_or_else(|_| panic!("{name}: `{value}` is not a number"))
                })
                .collect();
            (row[0].clone(), values)
        })
        .collect()
}

fn json(path: &Path) -> Value {
    serde_json::from_str(&fs::read_to_string(path).expect("JSON should exist")).expect("JSON")
}

#[allow(clippy::cast_precision_loss)]
fn rmse(values: &[f64], truth: &[f64]) -> f64 {
    let sum = values
        .iter()
        .zip(truth)
        .map(|(value, truth)| (value - truth).powi(2))
        .sum::<f64>();
    (sum / truth.len() as f64).sqrt()
}

#[test]
fn autospill_equals_r_autospill() {
    let data = fixture("autospill");
    let out = create_temp_dir("cytiq-parity-autospill");
    let spillover = out.join("spillover.csv");
    let debug = out.join("debug");
    cytiq(&[
        "autospill",
        "--controls",
        utf8(&data.join("controls.csv")),
        "--input-dir",
        utf8(&data),
        "--output",
        utf8(&spillover),
        "--matrix-kind",
        "spillover",
        "--debug-dir",
        utf8(&debug),
    ]);

    let mine = matrix(&spillover);
    let theirs = matrix(&data.join("upstream/spillover.csv"));
    assert_eq!(mine.len(), theirs.len());
    for (key, value) in &theirs {
        let delta = (mine[key] - value).abs();
        assert!(delta <= 1e-9, "{key:?}: cytiq {} vs R {value}", mine[key]);
    }
    let (_, counts) = read_csv(&data.join("upstream/gate_counts.csv"));
    let summary = json(&debug.join("summary.json"));
    for count in counts {
        let gated = summary["gate_stats"]
            .as_array()
            .expect("gate stats")
            .iter()
            .find(|gate| gate["dye"] == count[0].as_str())
            .unwrap_or_else(|| panic!("no gate for {}", count[0]))["gated_events"]
            .as_u64();
        assert_eq!(
            gated.map(|events| events.to_string()),
            Some(count[1].clone()),
            "{}",
            count[0]
        );
    }
}

#[test]
fn peacoqc_masks_equal_r_peacoqc() {
    let data = fixture("peacoqc");
    let out = create_temp_dir("cytiq-parity-peacoqc");
    let channels = fs::read_to_string(data.join("channels.txt")).expect("channels");
    for method in ["all", "mad", "it"] {
        let debug = out.join(format!("{method}_debug"));
        cytiq(&[
            "peacoqc",
            "--input",
            utf8(&data.join("sample.fcs")),
            "--output",
            utf8(&out.join(format!("{method}.fcs"))),
            "--channels",
            channels.trim(),
            "--method",
            method,
            "--debug-dir",
            utf8(&debug),
        ]);
        let (header, rows) = read_csv(&debug.join("mask.csv"));
        let good = header
            .iter()
            .position(|name| name == "is_good")
            .expect("is_good column");
        let mine = rows
            .iter()
            .map(|row| row[good] == "true")
            .collect::<Vec<_>>();
        let theirs = columns(&data.join(format!("upstream/{method}_mask.csv")))["good"]
            .iter()
            .map(|value| *value != 0.0)
            .collect::<Vec<_>>();
        assert_eq!(mine.len(), theirs.len(), "{method}");
        let differing = mine.iter().zip(&theirs).filter(|(a, b)| a != b).count();
        assert_eq!(differing, 0, "{method}: events where the masks differ");
    }
}

#[test]
fn autospectral_recovers_the_true_spectra_as_well_as_r() {
    let data = fixture("autospectral");
    let out = create_temp_dir("cytiq-parity-autospectral");
    cytiq(&[
        "autospectral",
        "--controls",
        utf8(&data.join("controls.csv")),
        "--samples",
        utf8(&data.join("samples.csv")),
        "--input-dir",
        utf8(&data),
        "--output",
        utf8(&out),
    ]);

    let truth = matrix(&data.join("truth/spectra.csv"));
    let mine = {
        let (header, rows) = read_csv(&out.join("references/fluorophore_spectra.csv"));
        rows.iter()
            .flat_map(|row| {
                header[2..].iter().zip(&row[2..]).map(|(detector, value)| {
                    (
                        (row[0].clone(), detector.clone()),
                        value.parse::<f64>().expect("spectrum value"),
                    )
                })
            })
            .collect::<HashMap<_, _>>()
    };
    let abundance = columns(&data.join("truth/sample_abundance.csv"));
    let upstream = columns(&data.join("upstream/unmix_truth_spectra.csv"));
    let unmixed = cytiq_fcs::FcsReader::open(out.join("unmixed/sample.unmixed.fcs"))
        .and_then(cytiq_fcs::FcsReader::read)
        .expect("unmixed FCS");
    let fluorophores = abundance
        .keys()
        .filter(|name| *name != "AF")
        .cloned()
        .collect::<Vec<_>>();
    for fluorophore in &fluorophores {
        let detectors = truth
            .keys()
            .filter(|(row, _)| row == fluorophore)
            .map(|(_, detector)| detector.clone())
            .collect::<Vec<_>>();
        let (a, b): (Vec<f64>, Vec<f64>) = detectors
            .iter()
            .map(|detector| {
                (
                    truth[&(fluorophore.clone(), detector.clone())],
                    mine[&(fluorophore.clone(), detector.clone())],
                )
            })
            .unzip();
        let dot = a.iter().zip(&b).map(|(a, b)| a * b).sum::<f64>();
        let norm = |values: &[f64]| values.iter().map(|value| value * value).sum::<f64>().sqrt();
        let cosine = dot / norm(&a) / norm(&b);
        assert!(cosine >= 0.9999, "{fluorophore}: spectrum cosine {cosine}");

        let column = unmixed
            .find_parameter(fluorophore)
            .unwrap_or_else(|| panic!("unmixed has no {fluorophore}"));
        let values = unmixed.data.columns[column].to_f64_vec();
        let ours = rmse(&values, &abundance[fluorophore]);
        let r = rmse(&upstream[fluorophore], &abundance[fluorophore]);
        // R unmixes with the true spectra, cytiq with the ones it estimated
        // from 2,000-event controls (within 1% of R's error when generated).
        assert!(
            ours <= 1.05 * r,
            "{fluorophore}: abundance RMSE {ours} against R on the true spectra {r}"
        );
    }
}

#[test]
fn cytoscan_features_and_flags_equal_r_cytoscan() {
    let data = fixture("cytoscan_exact");
    let out = create_temp_dir("cytiq-parity-cytoscan");
    let channels = fs::read_to_string(data.join("channels.txt")).expect("channels");
    for method in ["summary", "quantiles", "emd", "binning", "fingerprint"] {
        let result = out.join(method);
        cytiq(&[
            "cytoscan",
            "--input",
            utf8(&data.join("test")),
            "--reference",
            utf8(&data.join("reference")),
            "--output",
            utf8(&result),
            "--channels",
            channels.trim(),
            "--method",
            method,
            "--flag-method",
            "both",
        ]);
        let upstream = data.join("upstream");

        // Every event of every file on both sides: features equal R's, file
        // by file and column by column (R names fingerprint bins `X1`, ...).
        let mine = features(&result.join("cytoscan_features.csv"));
        let theirs = features(&upstream.join(format!("features_test_{method}.csv")));
        assert_eq!(mine.len(), theirs.len(), "{method}");
        for (filename, values) in &theirs {
            let ours = &mine[filename];
            assert_eq!(ours.len(), values.len(), "{method} {filename}");
            let delta = ours
                .iter()
                .zip(values)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            assert!(delta <= 1e-9, "{method} {filename}: max |delta| {delta}");
        }

        let (header, rows) = read_csv(&result.join("cytoscan_summary.csv"));
        let field = |name: &str| {
            let index = header
                .iter()
                .position(|column| column == name)
                .unwrap_or_else(|| panic!("summary has no {name}"));
            rows.iter()
                .map(|row| row[index].clone())
                .collect::<Vec<_>>()
        };
        let filenames = field("filename");
        let r_rows = |path: &Path| {
            let (header, rows) = read_csv(path);
            rows.into_iter()
                .map(|row| (row[0].clone(), (header.clone(), row)))
                .collect::<HashMap<_, _>>()
        };
        let value = |(header, row): &(Vec<String>, Vec<String>), name: &str| {
            let index = header
                .iter()
                .position(|column| column == name)
                .expect("column");
            row[index].parse::<f64>().unwrap_or(f64::NEG_INFINITY)
        };

        // Isolation forest: the same files score at least 0.5.
        let outlier = r_rows(&upstream.join(format!("outlier_{method}.csv")));
        for (filename, flagged) in filenames.iter().zip(field("is_outlier")) {
            let theirs = value(&outlier[filename], "score_seed42") >= 0.5;
            assert_eq!(flagged == "true", theirs, "{method} outlier {filename}");
        }

        // Novelty: Mclust's model, and the same files at or below its 5%
        // threshold (`log(dens())`, -Inf where dens() underflows).
        let meta = json(&upstream.join(format!("novelty_{method}.json")));
        let config = json(&result.join("cytoscan_config.json"));
        assert_eq!(
            config["diagnostics"]["novelty_model"], meta["default"]["model"],
            "{method}"
        );
        assert_eq!(
            config["diagnostics"]["novelty_components"], meta["default"]["G"],
            "{method}"
        );
        let threshold = meta["default"]["threshold"].as_f64().expect("threshold");
        let novelty = r_rows(&upstream.join(format!("novelty_{method}.csv")));
        for (filename, flagged) in filenames.iter().zip(field("is_novelty")) {
            let theirs = value(&novelty[filename], "ll_default") <= threshold;
            assert_eq!(flagged == "true", theirs, "{method} novelty {filename}");
        }
    }
}
